export function commands(actions){return [{id:'newFile',label:'Create File',run:actions.newFile},{id:'newFolder',label:'Create Folder',run:actions.newFolder},{id:'save',label:'Save Project',shortcut:'⌘/Ctrl S',run:actions.save},{id:'run',label:'Run Project',shortcut:'⌘/Ctrl Enter',run:actions.run},{id:'toggleTerminal',label:'Toggle Terminal',run:actions.toggleTerminal},{id:'toggleExplorer',label:'Toggle Explorer',shortcut:'⌘/Ctrl B',run:actions.toggleExplorer},{id:'export',label:'Download Project',run:actions.export},{id:'import',label:'Upload Project',run:actions.import},{id:'openPreview',label:'Open Preview',run:actions.preview}]}
